import json, pathlib, importlib

root = pathlib.Path(".")
fails = 0
for path in sorted((root / "examples").glob("*.json")):
    svc = path.stem
    mod = importlib.import_module(f"clients.{svc}")
    cases = json.loads(path.read_text())
    for i, case in enumerate(cases):
        try:
            got = mod.normalize(case["record"])
            outcome = {"ok": got}
        except ValueError:
            outcome = {"err": "ValueError"}
        if outcome != case["result"]:
            fails += 1
            print(f"MISMATCH {svc}[{i}]")
            print(" expected:", json.dumps(case["result"], ensure_ascii=False, sort_keys=True))
            print(" got     :", json.dumps(outcome, ensure_ascii=False, sort_keys=True))
print("failures:", fails)

