import copy, json, pathlib, importlib, py_compile

from clients._rules import apply_rules
print("split empties:", apply_rules({"x": ";; a ;; b ;;"}, [("split", "x", ";")])["x"])

# Compile all modules.
for p in pathlib.Path("clients").glob("*.py"):
    py_compile.compile(str(p), doraise=True)
print("compile: ok")

fails = 0
for path in sorted(pathlib.Path("examples").glob("*.json")):
    mod = importlib.import_module(f"clients.{path.stem}")
    for i, case in enumerate(json.loads(path.read_text())):
        original = copy.deepcopy(case["record"])
        try:
            outcome = {"ok": mod.normalize(case["record"])}
        except ValueError:
            outcome = {"err": "ValueError"}
        if outcome != case["result"]:
            fails += 1
            print("MISMATCH", path.stem, i)
        if case["record"] != original:
            fails += 1
            print("MUTATED", path.stem, i)
print("examples + immutability failures:", fails)

# Confirm every required module exposes normalize and dependency chain imports.
for name in ["accounts", "billing", "contacts", "customers", "invoices", "payments", "returns", "shipments"]:
    mod = importlib.import_module(f"clients.{name}")
    assert callable(mod.normalize)
print("modules: ok")

